package fetvisuals.gui;
import fetvisuals.render.FontRenderer; import fetvisuals.render.RenderUtils; import net.minecraft.client.gui.DrawContext; import net.minecraft.client.gui.screen.Screen; import net.minecraft.text.Text;
public final class AccountsScreen extends Screen {private final Screen parent;public AccountsScreen(Screen p){super(Text.literal("Accounts"));parent=p;}@Override public void render(DrawContext c,int mx,int my,float d){c.fill(0,0,width,height,0xF0080710);String title="Accounts";FontRenderer.draw(c,title,width/2-FontRenderer.width(title)/2,80,0xFFEAE7F2);String name=client.getSession().getUsername();RenderUtils.rounded(c,width/2-150,125,300,58,10,0xF0181422);FontRenderer.draw(c,"Current account",width/2-130,142,0xFF88838F);FontRenderer.draw(c,name,width/2-130,160,0xFFEAE7F2);FontRenderer.draw(c,"Esc  •  Back",width/2-FontRenderer.width("Esc  •  Back")/2,height-50,0xFF6F6A76);}public boolean keyPressed(int key,int scan,int mods){if(key==256){client.setScreen(parent);return true;}return super.keyPressed(key,scan,mods);}}
